using System.Net.Http.Json;using System.Text.Json;using SalekhPos.Desktop.Application.Management;
namespace SalekhPos.Desktop.Infrastructure.Management;
public sealed class HttpFeatureManager(HttpClient client):IFeatureManager{private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);public async Task<DesktopFeatureDecision> EvaluateAsync(Guid org,string key,CancellationToken ct){Validate(org,key);using var r=await client.GetAsync($"api/v1/organizations/{org:D}/features/{Uri.EscapeDataString(key)}",ct);r.EnsureSuccessStatusCode();var v=await r.Content.ReadFromJsonAsync<DesktopFeatureDecision>(Json,ct)??throw new InvalidOperationException("Empty feature response.");Validate(v);return v;}public async Task<DesktopFeatureOverride> OverrideAsync(Guid org,string key,bool enabled,string reason,CancellationToken ct){Validate(org,key);if(string.IsNullOrWhiteSpace(reason)||reason!=reason.Trim()||reason.Length>500)throw new ArgumentException("Reason is invalid.");using var r=await client.PutAsJsonAsync($"api/v1/organizations/{org:D}/features/{Uri.EscapeDataString(key)}/override",new{Enabled=enabled,Reason=reason},Json,ct);r.EnsureSuccessStatusCode();var v=await r.Content.ReadFromJsonAsync<DesktopFeatureOverride>(Json,ct)??throw new InvalidOperationException("Empty feature response.");if(v.OrganizationId!=org||v.Key!=key||v.Enabled!=enabled)throw new InvalidOperationException("Feature override response is invalid.");return v;}private static void Validate(Guid org,string key){if(org==Guid.Empty||string.IsNullOrWhiteSpace(key)||key.Length>128||key!=key.Trim())throw new ArgumentException("Feature scope is invalid.");}private static void Validate(DesktopFeatureDecision v){if(string.IsNullOrWhiteSpace(v.Key)||v.Key.Length>128||string.IsNullOrWhiteSpace(v.Source)||v.EvaluatedAt.Offset!=TimeSpan.Zero)throw new InvalidOperationException("Feature response is invalid.");}}